class PendingRates extends StatefulWidget{
  const PendingRates({super.key,required this.store,required this.rates});final PlatikStore store;final RateService rates;
  @override State<PendingRates> createState()=>_PendingRatesState();
}
class _PendingRatesState extends State<PendingRates>{
  bool busy=false;
  @override Widget build(BuildContext context){final data=widget.store.data;final all=[...widget.store.transactions,...widget.store.adjustments,if(data['openingBalance'] is Map)Map<String,dynamic>.from(data['openingBalance'] as Map)];final count=all.where((r)=>r['moneda']!=widget.store.currency&&!validConversion(r,widget.store.currency)).length;return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(count>0)Notice('$count importe(s) pendientes de conversión. Los importes originales se conservan y no se suman entre monedas diferentes.',color:C.lavender.withValues(alpha:.15)),TextButton.icon(onPressed:busy?null:()async{setState(()=>busy=true);try{final result=await widget.rates.refreshPending();if(context.mounted)toast(context,'${result.$1} equivalencias actualizadas · ${result.$2} pendientes');}catch(e){if(context.mounted)toast(context,e.toString());}finally{if(mounted)setState(()=>busy=false);}},icon:const Icon(Icons.refresh),label:Text(busy?'Consultando cotizaciones…':'Actualizar cotizaciones pendientes'))]);}
}
class Equivalent extends StatefulWidget{
  const Equivalent({super.key,required this.amount,required this.from,required this.to,required this.rates});final double amount;final String from,to;final RateService rates;
  @override State<Equivalent> createState()=>_EquivalentState();
}
class _EquivalentState extends State<Equivalent>{
  RowData? quote;bool loading=true;int token=0;
  @override void initState(){super.initState();load();}
  @override void didUpdateWidget(covariant Equivalent old){super.didUpdateWidget(old);if(old.from!=widget.from||old.to!=widget.to)load();}
  Future<void> load()async{final current=++token;final q=await widget.rates.quote(widget.from,widget.to);if(mounted&&current==token)setState((){quote=q;loading=false;});}
  @override Widget build(BuildContext context){if(widget.to.isEmpty||widget.to==widget.from)return const SizedBox.shrink();if(loading)return Text('Consultando equivalencia ${widget.to}…',style:body(11,color:C.sub));if(!RateService.usable(quote))return Text('Equivalencia ${widget.to}: cotización ${quote==null?'no disponible':'desactualizada'}',style:body(11,color:C.sub));final q=quote!;return InkWell(onTap:()=>showDialog<void>(context:context,builder:(context)=>AlertDialog(title:const Text('Detalle de la cotización'),content:SingleChildScrollView(child:Text('1 ${q['from']} = ${q['rate']} ${q['to']}\n${q['providerName']}\nTipo: referencia informativa\nPublicación: ${q['publishedAt']}\nConsulta: ${q['fetchedAt']}\nVigencia: ${RateService.freshness(q)}${q['viaCurrency']!=null?'\nTasa cruzada vía ${q['viaCurrency']}':''}\nFuentes declaradas: ${(q['underlyingProviders'] as List? ?? []).join(', ')}${q['legs']!=null?'\nPatas: ${q['legs']}':''}')),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cerrar'))])),child:Padding(padding:const EdgeInsets.only(top:6),child:Text('≈ ${money(rounded(widget.amount*number(q['rate']),widget.to),widget.to)} · referencia ${q['publishedAt'].toString().split('T').first} ⓘ',style:body(11,color:C.sub))));}
}

