    Group('Evolución de ingresos y egresos',subtitle:'Últimos 6 meses',children:[EvolutionChart(monthlySeries(store.transactions,c),currency:c)]),
    Group('Distribución de costos y gastos',subtitle:'Últimos 30 días',children:[CategoryChart(pie,currency:c)]),
