List<RowData> confirmedDigital(PlatikStore store){final deposits=store.deposits.where((d)=>d['estado']=='confirmado').toList();final hashes=deposits.map((d)=>d['txHash']).toSet();return [...deposits,...store.contributions.where((a)=>a['estado']=='confirmada'&&(a['txHash']==null||!hashes.contains(a['txHash'])))];}
String digitalSavings(PlatikStore store)=>confirmedDigital(store).fold<double>(0,(sum,r)=>sum+number(r['importe'])).toStringAsFixed(7).replaceFirst(RegExp(r'0+$'),'').replaceFirst(RegExp(r'\.$'),'');
int digitalCount(PlatikStore store)=>confirmedDigital(store).length;
